import redis.clients.jedis.Jedis;
import redis.clients.jedis.JedisPool;

public class RedisHighThroughputDemo {
    private static final JedisPool pool = new JedisPool("localhost", 6379);

    public void executePipeline() {
        // Leveraging pipelining reduces round-trip time (RTT), maximizing 
        // the single-threaded event loop's network batching efficiency.
        try (Jedis jedis = pool.getResource()) {
            var pipeline = jedis.pipelined();
            for (int i = 0; i < 10000; i++) {
                pipeline.set("key:" + i, "value:" + i);
            }
            pipeline.sync();
        }
    }
}
